#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Self-authored sleep_english script generator (NO external LLM).

由 WorkBuddy 直接撰写每个主题的英文对话 + 中文翻译；音标用本地 eng_to_ipa
生成，中文用 opencc 转繁体。每个主题内容均为针对该场景全新写出的真实句子，
不依赖任何外部大模型 API。

对话结构（pairwise / 成对）:
    THEMES[...]["pairs"] 是一组「对话对」，每个对话对 = [[A句, 中], [B句, 中]]，
    其中 B 句是 A 句的自然回应/接续。生成时按 1-2、3-4、5-6... 的顺序输出，
    保证相邻两句逻辑相关联系（A 说一句，B 自然接一句），而不是每句各自独立。

用法:
    python generate_self.py --out ai_scripts --lines 400 --force
    # --force 会先删除既有 script.json / checkpoint.json 再重新撰写（真正重生成）
"""
import argparse
import json
import os
import time
from pathlib import Path

from opencc import OpenCC
import eng_to_ipa as eip

_CC = OpenCC("s2t")
_IPA: dict[str, str] = {}


def ipa(text: str) -> str:
    text = text.strip()
    if not text:
        return "/ /"
    if text in _IPA:
        return _IPA[text]
    try:
        r = "/" + eip.convert(text) + "/"
    except Exception:
        r = "/" + text.lower() + "/"
    _IPA[text] = r
    return r


