            [["They called our row.", "叫到我们的排了。"], ["Time to board.", "该登机了。"]],
            [["Keep your ticket ready.", "把票准备好。"], ["In my hand, see.", "在我手上。"]],
            [["The shuttle to terminal three.", "往三号航厦的接驳车。"], ["It leaves every ten.", "每十分钟一班。"]],
