            [["Can we sit by the window?", "能坐窗边吗？"], ["Window seats are limited.", "窗边位有限。"]],
            [["We have a child with us.", "我们带小孩。"], ["We have high chairs.", "有儿童椅。"]],
            [["What is your phone number?", "您的电话？"], ["Zero one two, three four.", "012-34。"]],
            [["Should I confirm by text?", "要传简讯确认吗？"], ["Yes, we will text.", "会传简讯。"]],
            [["We may be late.", "我们可能迟到。"], ["We hold ten minutes.", "保留十分钟。"]],
            [["Is there a dress code?", "有服装规定吗？"], ["Smart casual is fine.", "便 smart 即可。"]],
            [["Can I change to eight?", "能改八点吗？"], ["Eight is open, sure.", "八点有空位。"]],
            [["A private room, possible?", "有包厢吗？"], ["We have one small room.", "有一间小包厢。"]],
            [["Do you take walk-ins?", "收不预约客吗？"], ["Yes, but waits are long.", "收，但要等。"]],
            [["We celebrate a birthday.", "我们庆生。"], ["We will bring a cake.", "会送蛋糕。"]],
            [["How long is the wait?", "要等多久？"], ["About twenty minutes.", "约二十分钟。"]],
            [["Is the table ready?", "位子好了吗？"], ["Just being set now.", "正在摆。"]],
            [["Can we add one guest?", "能加一位吗？"], ["We can squeeze in.", "可以加位。"]],
            [["The name on the list?", "名单上名字？"], ["Chen, party of four.", "陈，四人。"]],
            [["We are at the door.", "我们到门口了。"], ["I will seat you now.", "现在带位。"]],
            [["Window or booth?", "窗边还是卡座？"], ["Booth, please.", "卡座。"]],
