            [["Can we move indoors?", "能移到室内吗？"], ["If it rains, sure.", "下雨就可以。"]],
            [["The view is lovely here.", "这边景观很美。"], ["Best table, indeed.", "最好的位子。"]],
            [["We will order soon.", "我们马上点。"], ["Take your time.", "慢慢来。"]],
            [["Thanks for holding it.", "谢谢保留位子。"], ["Our pleasure.", "不客气。"]],
            [["See you at seven.", "七点见。"], ["We will be ready.", "我们准备好。"]],
            [["Is gratuity included?", "含服务费吗？"], ["Not in the reserve.", "订位不含。"]],
            [["Can I pay a deposit?", "能付订金吗？"], ["Not needed, just come.", "不用，直接来。"]],
