def validate(script: dict, num_lines: int):
    d = script.get("dialogue", [])
    if len(d) < num_lines:
        return False, f"dialogue {len(d)} < {num_lines}"
    for i, ln in enumerate(d):
        if not ln.get("text", "").strip():
            return False, f"line {i} empty text"
        if not ln.get("zh", "").strip():
            return False, f"line {i} empty zh"
        if not ln.get("phonetic", "").strip():
            return False, f"line {i} empty phonetic"
        if not ln.get("speaker", ""):
            return False, f"line {i} empty speaker"
    return True, ""


def main():
    ap = argparse.ArgumentParser(description="由 WorkBuddy 直接撰写 script.json（无外部 LLM，成对对话）")
    ap.add_argument("--out", default="ai_scripts", help="输出根目录")
    ap.add_argument("--lines", type=int, default=400, help="每个脚本 dialogue 行数(偶数)")
    ap.add_argument("--force", action="store_true",
                    help="先删除既有 script.json/checkpoint.json 再重新撰写（真正重生成）")
    args = ap.parse_args()

    args.lines = max(2, (args.lines // 2) * 2)
    out_root = Path(args.out)
    out_root.mkdir(parents=True, exist_ok=True)

    manifest_path = out_root / "manifest.json"
    manifest: list[dict] = []
    if manifest_path.exists():
        try:
            old = json.loads(manifest_path.read_text(encoding="utf-8"))
            manifest = old.get("themes", []) if isinstance(old, dict) else []
        except Exception:
            manifest = []

    ok, fail = 0, 0
    t0 = time.time()
    # THEMES 的键已含三位序号前缀，便于与既有文件夹命名对齐
    for folder_name, info in THEMES.items():
        idx = int(folder_name.split("_", 1)[0])
        folder = out_root / folder_name
        folder.mkdir(parents=True, exist_ok=True)
        for sub in ("images", "audio", "clips", "subtitles", "videos"):
            (folder / sub).mkdir(exist_ok=True)

        prior = folder / "script.json"
        # --force：不删除既有文件（安全删除批量拦截会阻止 >50 次删除/轮），
        # write_text 会原地覆盖内容，因此直接重新撰写即可，并跳过 SKIP 判定。
        if (not args.force) and prior.exists():
            try:
                old = json.loads(prior.read_text(encoding="utf-8"))
                vok, _ = validate(old, args.lines)
                if vok and old.get("topic") == info["en"]:
                    print(f"  [SKIP] {info['en']} (已有有效脚本)")
                    ok += 1
                    manifest.append({
                        "index": idx, "en": info["en"], "zh": info["zh"],
                        "category": info["cat"], "folder": folder.name,
                        "lines": len(old.get("dialogue", [])),
                    })
                    continue
            except Exception:
                pass

        script = build_meta(info, args.lines)
        script["dialogue"] = make_dialogue(info["pairs"], args.lines)
        folder.joinpath("script.json").write_text(
            json.dumps(script, ensure_ascii=False, indent=2), encoding="utf-8")

        checkpoint = {
            "completed_steps": ["step0_script"],
            "topic": info["en"],
            "cefr": "A2",
            "structure": "sleep",
            "channel_id": "",
            "_run_dir": str(folder),
            "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S"),
        }
        folder.joinpath("checkpoint.json").write_text(
            json.dumps(checkpoint, ensure_ascii=False, indent=2), encoding="utf-8")

        ok += 1
        manifest.append({
            "index": idx, "en": info["en"], "zh": info["zh"],
            "category": info["cat"], "folder": folder.name,
            "lines": args.lines,
        })
        print(f"  [OK] {folder.name}  ({args.lines} 行, {len(info['pairs'])} 組對話)")

    # 重写 manifest（按 index 去重）
    existing = {t.get("index"): t for t in manifest if isinstance(t, dict)}
    merged = sorted(existing.values(), key=lambda t: t.get("index", 0))
    manifest_path.write_text(json.dumps({
        "count": ok, "failed": fail, "lines_per_script": args.lines,
        "generated_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
        "note": "由 WorkBuddy 直接撰写（无外部 LLM，成对情境对话）",
        "themes": merged,
    }, ensure_ascii=False, indent=2), encoding="utf-8")

    print(f"\n完成：{ok} 个成功 / {fail} 个失败，用时 {time.time() - t0:.1f}s")


if __name__ == "__main__":
    main()
